class SerdeContext {
  serdeContext;
  setSerdeContext(context) {
    this.serdeContext = context;
    console.log("base", context);
  }
}

class HttpProtocol extends SerdeContext {
  setSerdeContext(context) {
    this.serdeContext = context;
    console.log("derived", context);
  }
}

class LeafProtocol extends HttpProtocol {
  setSerdeContext(context) {
    super.setSerdeContext(context);
    console.log("leaf", context);
  }
}

/** @param {SerdeContext} instance @param {number} value */
function assign(instance, value) {
  instance.setSerdeContext(value);
}

class ExpressionBase {
  applyContext(context) { console.log("expression-base", context); }
}
const ExpressionDerived = class extends ExpressionBase {
  applyContext(context) { console.log("expression-derived", context); }
};
/** @param {ExpressionBase} instance @param {number} value */
function assignExpression(instance, value) { instance.applyContext(value); }

export function run() {
  assign(new SerdeContext(), 11);
  assign(new HttpProtocol(), 22);
  assign(new LeafProtocol(), 33);
  assignExpression(new ExpressionDerived(), 44);
}
